            contentPadding: '@?',
            width: '@?',
            closeOnClickOutside: '<?',
            strategy: '@?',
            placement: '@?',
            disabled: '<?',
            autoFocus: '<?',
            confirmOnEnter: '<?',
            confirmText: '@?',
            cancelText: '@?',
            confirmIntent: '@?',
