            ariaLabel: '@?',
            labelPosition: '@?',
            size: '@?',
            containerBorder: '<?',
            indeterminate: '<?',
            trueValue: '<?',
            falseValue: '<?',
            disabled: '<?',
            onChange: '&?',
            name: '@?',
            tabIndex: '@?',
            hintText: '@?',
            errorText: '@?',
            errorMessages: '<?',
            showErrors: '<?'
