                             aria-label="{{ $ctrl.triggerLabel() }}"
                             ng-attr-aria-labelledby="{{ $ctrl.triggerLabelledBy() }}"
                             aria-required="{{ $ctrl.isRequired() }}"
                             aria-disabled="{{ !!$ctrl.opt.disabled }}"
                             aria-readonly="{{ !!$ctrl.opt.readonly }}"
