                                aria-busy="{{ !!($ctrl.opt.loading || $ctrl.rootLoading() || $ctrl.searching()) }}"
                                ng-show="!$ctrl.opt.loading && !$ctrl.rootLoading()">
                                <li class="aui-tree-select__spacer" role="none"
                                    aui-if="$ctrl.padTop > 0"
                                    ng-style="{height: $ctrl.padTop + 'px'}"></li>
